// Runtime benchmark for the first real Mira Atlas transformation, not compiler time.
// Reports JS generated by Mira versus a hand-written equivalent over identical data.
import {readFileSync, writeFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {fileURLToPath, pathToFileURL} from 'node:url';
import {performance} from 'node:perf_hooks';

const root=fileURLToPath(new URL('../',import.meta.url));
const site=resolve(root,'dist/studio');
const data=JSON.parse(readFileSync(resolve(site,'atlas-data.json'),'utf8'));
const {atlas_modules}=await import(pathToFileURL(resolve(site,'atlas-program.js')).href);
const base=data.modules;
const modules=Array.from({length:1000},(_,i)=>({...base[i%base.length],
  id:'sample.'+i,imports:base[i%base.length].imports}));
const reference=list=>list.map(item=>({
  id:item.id,title:item.title,path:item.path,group:item.group,
  language:item.language,lines:item.lines,dependencies:item.imports.length
}));
function measure(fn){
  for(let i=0;i<20;i++)fn();
  const samples=[];
  for(let i=0;i<100;i++){
    const start=performance.now();
    const result=fn();
    if(result.length!==modules.length)throw Error('Invalid benchmark output length');
    samples.push(performance.now()-start);
  }
  samples.sort((a,b)=>a-b);
  return {medianMs:samples[49],p95Ms:samples[94]};
}
const miraResult=atlas_modules(modules);
const jsResult=reference(modules);
if(JSON.stringify(miraResult)!==JSON.stringify(jsResult)){
  throw Error('Mira and hand-written JS produce different view models');
}
const report={
  description:'Transforming 1000 architecture modules to UI view models; no DOM rendering',
  samples:100,modules:modules.length,
  mira:measure(()=>atlas_modules(modules)),
  handwrittenJs:measure(()=>reference(modules)),
  generatedBytes:Buffer.byteLength(readFileSync(resolve(site,'atlas-program.js'),'utf8'))
};
writeFileSync(resolve(root,'dist/atlas-benchmark.json'),JSON.stringify(report,null,2)+'\n');
const lines=[
 '## Mira Atlas runtime transformation benchmark',
 '',
 '1000 module records, 100 samples per case, after 20 warmups; same Node process.',
 'Measures JS execution only (no compiler, DOM, downloads or rendering).',
 '',
 '| Implementation | Median (ms) | p95 (ms) |',
 '| --- | ---: | ---: |',
 '| Mira → JS | '+report.mira.medianMs.toFixed(3)+' | '+report.mira.p95Ms.toFixed(3)+' |',
 '| Handwritten JS | '+report.handwrittenJs.medianMs.toFixed(3)+' | '+report.handwrittenJs.p95Ms.toFixed(3)+' |',
 '',
 'Compiled atlas-program.js size: '+report.generatedBytes+' bytes.',
 'Observational only: CI runners vary; no JS performance pass/fail threshold.'
];
const summary=lines.join('\n');
console.log(summary);
if(process.env.GITHUB_STEP_SUMMARY){
  const {appendFileSync}=await import('node:fs');
  appendFileSync(process.env.GITHUB_STEP_SUMMARY,summary+'\n');
}
